parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "bottleneck_1": {
      "type": "string",
      "description": "The primary marketing, value proposition, or clarity bottleneck found on the site."
    },
    "bottleneck_2": {
      "type": "string",
      "description": "The secondary conversion, trust, or social proof bottleneck found on the site."
    },
    "bottleneck_3": {
      "type": "string",
      "description": "The tertiary call-to-action (CTA) or operational flow bottleneck found on the site."
    }
  },
  "required": [
    "bottleneck_1",
    "bottleneck_2",
    "bottleneck_3"
  ],
  "additionalProperties": false
}

parameters.text:
=You are an elite AI Operations Architect. Analyze the scraped web text from {{ $('Webhook').item.json.body.domain }} along with:

Team Size: {{ $('Webhook').item.json.body.q1_team_size }}

Workflow Bottleneck: {{ $('Webhook').item.json.body.q2_time_drain }}

Cost Impact: {{ $('Webhook').item.json.body.q3_cost_impact }}

Return 3 ranked AI automations tailored specifically to solve their exact bottleneck.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "automations": {
      "type": "array",
      "description": "Exactly 3 ranked high-leverage AI systems to build for this specific business based on their site and intake answers.",
      "items": {
        "type": "object",
        "properties": {
          "rank": { "type": "integer" },
          "title": { "type": "string", "description": "Short, punchy system name." },
          "description": { "type": "string", "description": "Specific description tailored to their site, tech stack, and time drain (2-3 sentences)." },
          "estimated_value": { "type": "string", "description": "Dollar value saved or gained per year (e.g., '$14,000/yr')." },
          "build_tier": { "type": "string", "description": "Complexity (e.g., 'Lightweight n8n workflow', 'Custom Webhook Integration')." },
          "payback_timeline": { "type": "string", "description": "Time to return investment (e.g., '3 weeks')." }
        },
        "required": ["rank", "title", "description", "estimated_value", "build_tier", "payback_timeline"],
        "additionalProperties": false
      },
      "minItems": 3,
      "maxItems": 3
    }
  },
  "required": ["automations"],
  "additionalProperties": false
}

